namespace sv_8208f4fe3682412db97d1861018daf3c.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyStateChanged();
        }
    }

    public string CurrentWarehouseName =>
        Warehouses.TryGetValue(_currentWarehouseId, out var name) ? name : _currentWarehouseId;

    public static IReadOnlyDictionary<string, string> Warehouses { get; } =
        new Dictionary<string, string>
        {
            ["WH-001"] = "Warehouse A — Main Distribution",
            ["WH-002"] = "Warehouse B — East Regional",
            ["WH-003"] = "Warehouse C — West Regional",
            ["WH-004"] = "Warehouse D — Cold Storage",
        };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

namespace sv_8208f4fe3682412db97d1861018daf3c.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentLowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate latency and return a random count between 0 and 15
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Updates the cached count and notifies all subscribers.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        CurrentLowStockCount = await GetLowStockCountAsync(warehouseId);
        NotifySubscribers();
    }

    private void NotifySubscribers() => OnAlertCountChanged?.Invoke();
}

