@using sv_8208f4fe3682412db97d1861018daf3c.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-1 text-white small">Current Warehouse</label>
    <select class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "WH-001";
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@using sv_8208f4fe3682412db97d1861018daf3c.Services
@inject InventoryAlertService AlertService
@inject WarehouseStateService WarehouseState
@implements IDisposable

<span class="alert-badge">
    @if (AlertService.CurrentLowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@AlertService.CurrentLowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnAlertUpdated;
        WarehouseState.OnChange += OnWarehouseChanged;
    }

    private void OnAlertUpdated()
    {
        InvokeAsync(StateHasChanged);
    }

    private async void OnWarehouseChanged()
    {
        await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnAlertUpdated;
        WarehouseState.OnChange -= OnWarehouseChanged;
    }
}

@page "/dashboard"
@using sv_8208f4fe3682412db97d1861018daf3c.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">
    Viewing: <strong>@WarehouseState.CurrentWarehouseName</strong>
</p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(AlertService.CurrentLowStockCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentLowStockCount > 5 ? "text-danger" : "text-success")">
                    @AlertService.CurrentLowStockCount
                </p>
                <p class="text-muted small">
                    Items below minimum level
                </p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="mt-2">
                    @if (_isPolling)
                    {
                        <span class="badge bg-success">Active — every 10s</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary">Stopped</span>
                    }
                </p>
                <p class="text-muted small">Last refresh: @_lastRefresh.ToString("HH:mm:ss")</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Warehouse</h5>
                <p class="mt-2"><code>@WarehouseState.CurrentWarehouseId</code></p>
                <p class="text-muted small">Change via the top-bar dropdown</p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private DateTime _lastRefresh = DateTime.Now;

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertUpdated;

        await StartPollingAsync();
    }

    private async Task StartPollingAsync()
    {
        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        _isPolling = true;

        // Initial fetch
        await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
        _lastRefresh = DateTime.Now;

        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken token)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(token))
            {
                await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
                _lastRefresh = DateTime.Now;
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose or warehouse change
        }
    }

    private async void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse
        await StartPollingAsync();
        await InvokeAsync(StateHasChanged);
    }

    private void OnAlertUpdated()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _isPolling = false;
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
